10	import org.springframework.data.domain.Pageable;
11	import org.springframework.data.jpa.domain.Specification;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	/**
16	 * Application service for product search and later zero-hit recording orchestration.
17	 */
18	@Service
19	public class ProductSearchService {
20	
21		private final ProductRepository productRepository;
22		private final ProductMapper productMapper;
23		private final ZeroHitRecordingService zeroHitRecordingService;
24	
25		public ProductSearchService(
26				ProductRepository productRepository,
27				ProductMapper productMapper,
28				ZeroHitRecordingService zeroHitRecordingService) {
29			this.productRepository = productRepository;
30			this.productMapper = productMapper;
31			this.zeroHitRecordingService = zeroHitRecordingService;
32		}
33	
34		/**
35		 * Searches products and records zero-hit demand only for valid non-empty searches with zero results.
36		 *
37		 * @param keyword raw search keyword
38		 * @param limit maximum number of rows
39		 * @param category optional category filter
40		 * @param sort frontend sort token
41		 * @return search response
42		 */
43		@Transactional
44		public ProductSearchResponse search(String keyword, Integer limit, String category, String sort) {
45			String trimmedKeyword = keyword == null ? "" : keyword.trim();
46			Specification<Product> specification = ProductSpecifications.categoryIn(
47					ProductRequestOptions.normalizeCategories(category));
48			if (!trimmedKeyword.isBlank()) {
49				specification = specification.and(ProductSpecifications.containsKeyword(trimmedKeyword));
50			}
51	
52			Pageable pageable = ProductRequestOptions.toPageable(limit, sort);
53			List<Product> products = productRepository.findAll(specification, pageable).getContent();
54			long totalCount = productRepository.count(specification);
55			List<ProductDto> items = products.stream().map(productMapper::toDto).toList();
56			boolean zeroHitRecorded = false;
57			if (!trimmedKeyword.isBlank() && totalCount == 0) {
58				zeroHitRecordingService.record(trimmedKeyword);
59				zeroHitRecorded = true;
60			}
61			return new ProductSearchResponse(items, totalCount, zeroHitRecorded);
62		}
63	}

