 20	/**
 21	 * Authenticates the single MVP admin account and manages opaque bearer sessions.
 22	 * Opaque in-memory tokens keep the OSS demo free of token signing secrets while
 23	 * still allowing explicit expiry and Spring Security authorization.
 24	 */
 25	@Service
 26	public class AdminAuthService {
 27	
 28		private static final String ADMIN_ROLE = "ADMIN";
 29		private static final int TOKEN_BYTES = 32;
 30	
 31		private final AdminProperties adminProperties;
 32		private final PasswordEncoder passwordEncoder;
 33		private final Clock clock;
 34		private final SecureRandom secureRandom = new SecureRandom();
 35		private final Map<String, AdminSession> sessions = new ConcurrentHashMap<>();
 36	
 37		public AdminAuthService(AdminProperties adminProperties, PasswordEncoder passwordEncoder, Clock clock) {
 38			this.adminProperties = adminProperties;
 39			this.passwordEncoder = passwordEncoder;
 40			this.clock = clock;
 41		}
 42	
 43		/**
 44		 * Validates configured admin credentials and issues a time-limited opaque token.
 45		 *
 46		 * @param username submitted username
 47		 * @param password submitted password
 48		 * @return successful login response
 49		 */
 50		public LoginResponse login(String username, String password) {
 51			if (!isConfigured()
 52					|| username == null
 53					|| password == null
 54					|| !adminProperties.username().equals(username)
 55					|| !passwordEncoder.matches(password, adminProperties.password())) {
 56				throw new AuthenticationFailedException("Invalid admin credentials");
 57			}
 58	
 59			AdminUserDto user = new AdminUserDto(adminProperties.username(), ADMIN_ROLE);
 60			String token = issueToken(user);
 61			return new LoginResponse(true, token, user);
 62		}
 63	
 64		/**
 65		 * Validates a bearer token and returns the associated admin identity when active.
 66		 *
 67		 * @param token opaque bearer token
 68		 * @return admin identity if token exists and has not expired
 69		 */
 70		public Optional<AdminUserDto> validateToken(String token) {
 71			if (token == null || token.isBlank()) {
 72				return Optional.empty();
 73			}
 74			AdminSession session = sessions.get(token);
 75			if (session == null) {
 76				return Optional.empty();
 77			}
 78			if (!session.expiresAt().isAfter(Instant.now(clock))) {
 79				sessions.remove(token);
 80				return Optional.empty();
 81			}
 82			return Optional.of(session.user());
 83		}
 84	
 85		private boolean isConfigured() {
 86			return adminProperties.username() != null
 87					&& !adminProperties.username().isBlank()
 88					&& adminProperties.password() != null
 89					&& !adminProperties.password().isBlank();
 90		}
 91	
 92		private String issueToken(AdminUserDto user) {
 93			byte[] bytes = new byte[TOKEN_BYTES];
 94			secureRandom.nextBytes(bytes);
 95			String token = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
 96			Duration ttl = adminProperties.tokenTtl() == null ? Duration.ofHours(8) : adminProperties.tokenTtl();
 97			sessions.put(token, new AdminSession(user, Instant.now(clock).plus(ttl)));
 98			return token;
 99		}
100	
101		private record AdminSession(AdminUserDto user, Instant expiresAt) {
102		}
103	}

