 15	/**
 16	 * Orchestrates prompt construction, product context lookup, live AI generation, and fallback answers.
 17	 */
 18	@Service
 19	public class AiConsultationService {
 20	
 21		private static final Logger LOGGER = LoggerFactory.getLogger(AiConsultationService.class);
 22	
 23		private final ProductRepository productRepository;
 24		private final AiPromptBuilder aiPromptBuilder;
 25		private final AiProviderClient aiProviderClient;
 26	
 27		public AiConsultationService(
 28				ProductRepository productRepository,
 29				AiPromptBuilder aiPromptBuilder,
 30				AiProviderClient aiProviderClient) {
 31			this.productRepository = productRepository;
 32			this.aiPromptBuilder = aiPromptBuilder;
 33			this.aiProviderClient = aiProviderClient;
 34		}
 35	
 36		/**
 37		 * Produces administrator-facing business advice without exposing prompts, tokens, or secrets in the response.
 38		 *
 39		 * @param request consultation request
 40		 * @return AI-backed, fallback, or controlled error answer
 41		 */
 42		@Transactional(readOnly = true)
 43		public AiConsultResponse consult(AiConsultRequest request) {
 44			AiPromptContext context = new AiPromptContext(
 45					productRepository.findDistinctCategories(),
 46					productRepository.findDistinctManufacturers());
 47			String prompt = aiPromptBuilder.build(request, context);
 48	
 49			try {
 50				Optional<String> generated = aiProviderClient.generate(prompt);
 51				AiConsultResponse response = generated
 52						.map(answer -> new AiConsultResponse(answer, ProviderStatus.LIVE))
 53						.orElseGet(() -> new AiConsultResponse(fallbackAnswer(request, context), ProviderStatus.FALLBACK));
 54				LOGGER.info("ai_consultation providerStatus={}", response.providerStatus());
 55				return response;
 56			} catch (AiProviderException exception) {
 57				AiConsultResponse response = new AiConsultResponse(providerErrorAnswer(request, context), ProviderStatus.ERROR);
 58				LOGGER.warn("ai_consultation providerStatus={}", response.providerStatus());
 59				return response;
 60			}
 61		}
 62	
 63		private String fallbackAnswer(AiConsultRequest request, AiPromptContext context) {
 64			return """
 65					結論
 66					AI_API_KEY が未設定のためデモ用の回答です。検索語「%s」は、既存カテゴリと照らして小さく検証する価値があります。
 67	
 68					理由
 69					Zero Hit は商品が見つからなかった需要の兆候です。hit count が %s のため、まずは問い合わせ数、季節、既存カテゴリとの近さを確認してください。
 70	
 71					仕入れ候補
 72					既存カテゴリでは %s を起点に、関連するブランドやサイズ展開を少量から検討してください。
 73	
 74					注意点
 75					調達リスク、シーズン終盤の在庫滞留、代替商品の有無を確認し、いきなり大量発注しないでください。
 76	
 77					次のアクション
 78					検索ログを 1 週間追跡し、同義語で商品名や説明文を改善したうえで、必要なら少量仕入れまたは予約受付を試してください。
 79					""".formatted(displayKeyword(request), displayHitCount(request), firstOrUnknown(context.categories()));
 80		}
 81	
 82		private String providerErrorAnswer(AiConsultRequest request, AiPromptContext context) {
 83			return """
 84					結論
 85					AI provider への接続で一時的な問題が発生しました。backend は継続稼働しているため、暫定判断として検索語「%s」を保留リストに入れてください。
 86	
 87					理由
 88					Zero Hit の hit count は %s です。ライブ回答が復旧するまで、既存カテゴリ「%s」と関連する商品で代替可能かを確認します。
 89	
 90					仕入れ候補
 91					関連カテゴリの商品説明を見直し、近いメーカーや商品タイプを候補として棚卸ししてください。
 92	
 93					注意点
 94					外部 AI の失敗を仕入れ判断の停止理由にせず、調達リスクと季節性を人手で確認してください。
 95	
 96					次のアクション
 97					AI 設定と provider 状態を確認し、復旧後に同じ質問を再実行してください。
 98					""".formatted(displayKeyword(request), displayHitCount(request), firstOrUnknown(context.categories()));
 99		}
100	
101		private String displayKeyword(AiConsultRequest request) {
102			return request.keyword() == null || request.keyword().isBlank() ? "不明" : request.keyword().trim();
103		}
104	
105		private String displayHitCount(AiConsultRequest request) {
106			return request.hitCount() == null ? "不明" : request.hitCount().toString();
107		}
108	
109		private String firstOrUnknown(java.util.List<String> values) {
110			return values == null || values.isEmpty() ? "不明" : values.getFirst();
111		}
112	}

