 19	import org.springframework.transaction.annotation.Transactional;
 20	
 21	/**
 22	 * Records valid zero-hit product searches as aggregated demand rows.
 23	 */
 24	@Service
 25	public class ZeroHitRecordingService {
 26	
 27		private static final Logger LOGGER = LoggerFactory.getLogger(ZeroHitRecordingService.class);
 28	
 29		private final ZeroHitSearchRepository zeroHitSearchRepository;
 30		private final ProductRepository productRepository;
 31		private final KeywordNormalizer keywordNormalizer;
 32		private final OpportunityLossCalculator opportunityLossCalculator;
 33		private final ZeroHitPriorityDecider priorityDecider;
 34		private final Clock clock;
 35	
 36		public ZeroHitRecordingService(
 37				ZeroHitSearchRepository zeroHitSearchRepository,
 38				ProductRepository productRepository,
 39				KeywordNormalizer keywordNormalizer,
 40				OpportunityLossCalculator opportunityLossCalculator,
 41				ZeroHitPriorityDecider priorityDecider,
 42				Clock clock) {
 43			this.zeroHitSearchRepository = zeroHitSearchRepository;
 44			this.productRepository = productRepository;
 45			this.keywordNormalizer = keywordNormalizer;
 46			this.opportunityLossCalculator = opportunityLossCalculator;
 47			this.priorityDecider = priorityDecider;
 48			this.clock = clock;
 49		}
 50	
 51		/**
 52		 * Upserts a non-blank zero-hit keyword within a transaction.
 53		 *
 54		 * @param keyword raw user keyword
 55		 * @return persisted zero-hit aggregate
 56		 */
 57		@Transactional
 58		public ZeroHitSearch record(String keyword) {
 59			String normalizedKeyword = keywordNormalizer.normalize(keyword);
 60			if (normalizedKeyword.isBlank()) {
 61				throw new IllegalArgumentException("keyword must not be blank");
 62			}
 63			String displayKeyword = keyword.trim();
 64			Instant now = Instant.now(clock);
 65	
 66			return zeroHitSearchRepository.findByNormalizedKeyword(normalizedKeyword)
 67					.map(existing -> updateExisting(existing, displayKeyword, now))
 68					.orElseGet(() -> insertFirst(displayKeyword, normalizedKeyword, now));
 69		}
 70	
 71		private ZeroHitSearch updateExisting(ZeroHitSearch existing, String displayKeyword, Instant now) {
 72			int nextHitCount = existing.getHitCount() + 1;
 73			BigDecimal opportunityLoss = opportunityLossCalculator.calculate(nextHitCount, productRepository.averagePrice());
 74			Priority priority = priorityDecider.decide(nextHitCount);
 75			existing.recordRepeat(displayKeyword, opportunityLoss, priority, now);
 76			ZeroHitSearch saved = zeroHitSearchRepository.save(existing);
 77			LOGGER.info(
 78					"zero_hit_recorded normalizedKeyword={} hitCount={} priority={}",
 79					saved.getNormalizedKeyword(),
 80					saved.getHitCount(),
 81					saved.getPriority());
 82			return saved;
 83		}
 84	
 85		private ZeroHitSearch insertFirst(String displayKeyword, String normalizedKeyword, Instant now) {
 86			BigDecimal opportunityLoss = opportunityLossCalculator.calculate(1, productRepository.averagePrice());
 87			Priority priority = priorityDecider.decide(1);
 88			ZeroHitSearch zeroHitSearch = ZeroHitSearch.firstHit(displayKeyword, normalizedKeyword, opportunityLoss, now);
 89			zeroHitSearch.updateDemandSignals(opportunityLoss, priority);
 90			try {
 91				ZeroHitSearch saved = zeroHitSearchRepository.saveAndFlush(zeroHitSearch);
 92				LOGGER.info(
 93						"zero_hit_recorded normalizedKeyword={} hitCount={} priority={}",
 94						saved.getNormalizedKeyword(),
 95						saved.getHitCount(),
 96						saved.getPriority());
 97				return saved;
 98			}
 99			catch (DataIntegrityViolationException duplicate) {
100				return zeroHitSearchRepository.findByNormalizedKeyword(normalizedKeyword)
101						.map(existing -> updateExisting(existing, displayKeyword, now))
102						.orElseThrow(() -> duplicate);
103			}
104		}
105	}

