27	
28		/**
29		 * Lists products with optional category filtering and validated sorting.
30		 *
31		 * @param limit maximum number of rows
32		 * @param category optional category filter
33		 * @param sort frontend sort token
34		 * @return product list response
35		 */
36		@Transactional(readOnly = true)
37		public ProductListResponse listProducts(Integer limit, String category, String sort) {
38			Pageable pageable = ProductRequestOptions.toPageable(limit, sort);
39			Specification<Product> specification = ProductSpecifications.categoryIn(
