 1	package com.codexskishop.service;
 2	
 3	import java.util.List;
 4	
 5	import org.springframework.data.domain.PageRequest;
 6	import org.springframework.data.domain.Pageable;
 7	import org.springframework.data.domain.Sort;
 8	
 9	/**
10	 * Validates and normalizes product list/search query parameters.
11	 */
12	public final class ProductRequestOptions {
13	
14		public static final int DEFAULT_LIMIT = 20;
15		public static final int MAX_LIMIT = 100;
16		public static final String DEFAULT_SORT = "createdAt,desc";
17	
18		private ProductRequestOptions() {
19		}
20	
21		/**
22		 * Converts nullable request parameters into safe repository options.
23		 *
24		 * @param limit requested maximum number of rows
25		 * @param sort requested sort token
26		 * @return pageable with validated limit and sort
27		 */
28		public static Pageable toPageable(Integer limit, String sort) {
29			int safeLimit = limit == null ? DEFAULT_LIMIT : limit;
30			if (safeLimit < 1 || safeLimit > MAX_LIMIT) {
31				throw new IllegalArgumentException("limit must be between 1 and 100");
32			}
33			return PageRequest.of(0, safeLimit, toSort(sort));
34		}
35	
36		/**
37		 * Maps the frontend sort contract to entity field sorting.
38		 *
39		 * @param sort requested sort token
40		 * @return Spring Data sort
41		 */
42		public static Sort toSort(String sort) {
43			String requestedSort = sort == null || sort.isBlank() ? DEFAULT_SORT : sort.trim();
44			return switch (requestedSort) {
45				case "createdAt,desc" -> Sort.by(Sort.Direction.DESC, "createdAt").and(Sort.by("name"));
46				case "price,asc" -> Sort.by(Sort.Direction.ASC, "price").and(Sort.by("name"));
47				case "price,desc" -> Sort.by(Sort.Direction.DESC, "price").and(Sort.by("name"));
48				default -> throw new IllegalArgumentException("sort must be one of createdAt,desc, price,asc, or price,desc");
49			};
50		}
51	
52		/**
53		 * Normalizes category filter aliases used by the current frontend into backend seed categories.
54		 *
55		 * @param category raw category query parameter
56		 * @return categories to filter by, or empty when all categories should be included
57		 */
58		public static List<String> normalizeCategories(String category) {
59			if (category == null || category.isBlank() || "all".equalsIgnoreCase(category.trim())) {
60				return List.of();
61			}
62			String normalized = category.trim().toLowerCase();
63			return switch (normalized) {
64				case "boots" -> List.of("ski boots");
65				case "accessories" -> List.of("bindings", "helmets", "gloves", "wax", "tuning goods");
66				default -> List.of(normalized);
67			};
68		}
69	}

