 3	import java.util.Locale;
 4	
 5	import org.springframework.stereotype.Component;
 6	
 7	/**
 8	 * Normalizes user search keywords so repeated zero-hit demand aggregates into one row.
 9	 */
10	@Component
11	public class KeywordNormalizer {
12	
13		/**
14		 * Trims, lowercases, and collapses repeated whitespace.
15		 *
16		 * @param keyword raw user keyword
17		 * @return normalized keyword, or an empty string when input is null or blank
18		 */
19		public String normalize(String keyword) {
20			if (keyword == null) {
21				return "";
22			}
23			return keyword.trim()
24					.toLowerCase(Locale.ROOT)
25					.replaceAll("\\s+", " ");
26		}
27	}

